function primes_upto(n::Integer)
    n >= 0 || throw(ArgumentError("n must be non-negative, got $n"))
    N = Int(n)                                      # all arithmetic in Int: i*i overflows Int8
    N < 2 && return typeof(n)[]
    composite = falses(N)
    for i in 2:isqrt(N)
        composite[i] && continue
        for m in i*i:i:N
            composite[m] = true
        end
    end
    return typeof(n)[i for i in 2:N if !composite[i]]
end

# Checks
@assert primes_upto(1) == Int[] && primes_upto(0) == Int[]
@assert length(primes_upto(Int8(127))) == 31 && last(primes_upto(Int8(127))) == Int8(127)
@assert primes_upto(UInt16(65535)) isa Vector{UInt16}

err = try primes_upto(-1); nothing catch e; e end
@assert err isa ArgumentError && occursin("non-negative", err.msg)
```

The result element type is `typeof(n)`, so callers that pass `Int8` or `UInt16` get a vector of that type, including the empty case (`typeof(n)[]`, not `Int[]`). The sieve itself runs in `Int`: with `Int8` the product `12 * 12` would wrap, so the marking loop converts once at the top. A `BitVector` stores one bit per number.

```julia
function columns_of(rows::AbstractVector{<:AbstractVector})
    ncols = maximum(length, rows; init = 0)
    T = Union{Missing,mapreduce(eltype, promote_type, rows; init = Union{})}
    return [T[i <= length(r) ? r[i] : missing for r in rows] for i in 1:ncols]
end

# Checks
cols = columns_of([[1, 2, 3], [4, 5], [6]])
@assert isequal(cols, [[1, 4, 6], [2, 5, missing], [3, missing, missing]])
@assert columns_of(Vector{Int}[]) == []
@assert eltype(cols[1]) == Union{Missing,Int}
@assert isequal(columns_of([["a"], ["b", "c"]]), [["a", "b"], [missing, "c"]])
```

Each output column is built with an explicit `Union{Missing,T}` element type so the result is concretely typed even when no cell is missing. `maximum(length, rows; init = 0)` handles the empty table. Use `isequal` rather than `==` when comparing results that contain `missing`.

