```julia
function insertion_sort!(v::AbstractVector; lt = isless)
    for i in firstindex(v)+1:lastindex(v)
        x = v[i]
        j = i - 1
        while j >= firstindex(v) && lt(x, v[j])
            v[j+1] = v[j]
            j -= 1
        end
        v[j+1] = x
    end
    return v
end

# Checks
@assert insertion_sort!([3, 1, 2]) == [1, 2, 3]
@assert insertion_sort!(["pear", "apple", "fig"]) == ["apple", "fig", "pear"]
@assert insertion_sort!([3, 1, 2]; lt = >) == [3, 2, 1]
w = rand(50)
@assert insertion_sort!(copy(w)) == sort(w)
```

Indexing goes through `firstindex`/`lastindex`, so the function also works on offset arrays and views, and `lt` lets callers choose the order. Insertion sort is O(n^2) in the worst case but O(n) on nearly sorted input and stable, which is why it is still used for small ranges inside library sorts. For real work call `sort!`.

