is_square(n::Integer) = n >= 0 && isqrt(n)^2 == n

function perfect_power(n::Integer)
    n >= 2 || return nothing
    for e in 2:floor(Int, log2(n))
        r = round(Integer, big(n)^(1 / e))
        for c in (r - 1, r, r + 1)
            c >= 2 && big(c)^e == n && return (Int(c), e)
        end
    end
    return nothing
end

# Checks
@assert is_square(0) && is_square(144) && !is_square(145) && !is_square(-4)
@assert is_square(10^18) && !is_square(10^18 + 1)
@assert perfect_power(64) in ((8, 2), (4, 3), (2, 6))
for m in (125, 1000, 4096, 3^13)
    b, e = perfect_power(m)
    @assert b^e == m
end
```

`isqrt` returns the exact integer square root, so squaring it back tests squareness with no rounding issues even near 10^18, where `sqrt` on a `Float64` can be off. For general powers the floating-point root only supplies a guess, and the neighbors are verified with exact integer arithmetic.

```julia
const ROMAN = [1000 => "M", 900 => "CM", 500 => "D", 400 => "CD", 100 => "C", 90 => "XC",
               50 => "L", 40 => "XL", 10 => "X", 9 => "IX", 5 => "V", 4 => "IV", 1 => "I"]

function to_roman(n::Integer)
    1 <= n <= 3999 || throw(ArgumentError("Roman numerals cover 1:3999, got $n"))
    io = IOBuffer()
    for (value, sym) in ROMAN
        while n >= value
            print(io, sym)
            n -= value
        end
    end
    return String(take!(io))
end

function from_roman(s::AbstractString)
    vals = Dict('I' => 1, 'V' => 5, 'X' => 10, 'L' => 50, 'C' => 100, 'D' => 500, 'M' => 1000)
    isempty(s) && throw(ArgumentError("empty string"))
    all(c -> haskey(vals, c), s) || throw(ArgumentError("invalid Roman numeral: $s"))
    v = [vals[c] for c in s]
    return sum(i < length(v) && v[i] < v[i+1] ? -v[i] : v[i] for i in eachindex(v))
end

# Checks
@assert to_roman(1994) == "MCMXCIV"
@assert to_roman(4) == "IV" && to_roman(3999) == "MMMCMXCIX"
@assert try to_roman(0); false catch e; e isa ArgumentError end
@assert try from_roman("ABC"); false catch e; e isa ArgumentError end
```

A descending table that includes the subtractive pairs (`CM`, `IV`, ...) lets a greedy loop produce the canonical form. Reading backwards, a symbol smaller than its right neighbor is subtracted. The table is a `const`, so access is type-stable.

